#!/usr/bin/env python3
import json,html,re,os
from pathlib import Path
from urllib.parse import quote
from markdown_it import MarkdownIt
ROOT=Path(__file__).resolve().parent
LIB=ROOT.parents[2]/'materials/wallstreetcn'
WORK=LIB.parent.parent
md=MarkdownIt('commonmark',{'html':False})
E=lambda x:html.escape(x if isinstance(x,str) else json.dumps(x,ensure_ascii=False),quote=True)
def read(p):return json.loads(p.read_text())
def scalar(x):return x if isinstance(x,str) else json.dumps(x,ensure_ascii=False)
def rich(x):
 if not x:return ''
 if isinstance(x,list):return '<ul>'+''.join('<li>'+rich(v)+'</li>'for v in x)+'</ul>'
 if isinstance(x,dict):return '<dl>'+''.join('<dt>'+E(k)+'</dt><dd>'+rich(v)+'</dd>'for k,v in x.items())+'</dl>'
 return md.render(str(x))
def href(path):return quote(os.path.relpath(path,ROOT),safe='/')
def link(label,path):return f'<a href="{E(href(path))}">{E(label)}</a>'
def content():
 meta=read(ROOT/'run_manifest.json');review=read(ROOT/'review.json') if (ROOT/'review.json').exists() else {}
 results=[read(p) for p in sorted((ROOT/'成果').glob('*.json'))]
 cards=[];table=[]
 kinds={'existing_update':'更新旧页','new_concept':'新概念','child_concept':'子概念','new_mechanism':'新关系','child_mechanism':'子关系','event':'事件分析','section':'页内章节'}
 for d in results:
  rid=d['run_id'];case='ai' if rid.startswith('ai_') else 'korea';structures=d.get('structures',[]);srows=[]
  for s in structures:
   kind=s.get('kind','');srows.append('<section class="structure"><h4>'+E(s.get('name',''))+' <span class="pill">'+E(kinds.get(kind,kind))+'</span></h4>'+''.join(f'<div class="field"><b>{label}</b>{rich(s.get(key,""))}</div>' for key,label in [('parent','父项／关联'),('inherits','继承内容'),('difference','具体差异'),('why_register','独立维护理由'),('inline_alternative','旧页／章节方案'),('decision','本次建议')])+'</section>')
  passages=''.join(f'<section class="passage"><p class="eyebrow">{E(p.get("location",""))}</p><blockquote>{E(p.get("quote",""))}</blockquote>{rich(p.get("analysis",""))}<div class="method">{rich(p.get("method",""))}</div></section>' for p in d.get('passages',[]))
  rd=d.get('reading',{});reading=''
  for key,label in [('documents','说明文件'),('graph_pages','相关正文'),('figures','图片')]:
   reading+=f'<h5>{label}</h5><ul>'
   for p in rd.get(key,[]):
    actual=WORK/str(p)
    reading+='<li>'+(link(str(p),actual) if actual.exists() else E(p))+'</li>'
   reading+='</ul>'
  comment=review.get('runs',{}).get(rid,'')
  summ=d.get('summary','');names='；'.join(s.get('name','') for s in structures)
  table.append(f'<tr data-case="{case}"><td><a href="#{rid}">{E(rid)}</a></td><td>{E(summ)}</td><td>{E(names)}</td><td>{rich(comment)}</td></tr>')
  search=E(' '.join([rid,scalar(summ),scalar(d.get('problem','')),names]))
  cards.append(f'''<details class="agent" id="{rid}" data-case="{case}" data-search="{search}"><summary><span class="run">{E(rid)}</span><span>{E(summ)}</span><span class="expand">展开</span></summary><div class="inside"><h3>文章问题</h3>{rich(d.get('problem',''))}<h3>关键论述与分析</h3>{passages}<h3>内容与结构选择</h3>{''.join(srows)}<h3>{E(d.get('sample_title','内容样稿'))}</h3><div class="sample">{rich(d.get('sample',''))}</div><h3>具体限制</h3>{rich(d.get('limitations',''))}<h3>对纲领与说明的反馈</h3>{rich(d.get('guidance_feedback',''))}<details class="reading"><summary>实际阅读范围（agent自报）</summary>{reading}</details><p>{link('查看原始JSON',ROOT/'成果'/f'{rid}.json')}</p></div></details>''')
 cases=[]
 for key,c in meta['cases'].items():
  p=WORK/c['markdown'];fig=3 if key=='ai' else 6;image=p.parent/'assets'/f'figure_{fig:03d}.png'
  c_review=review.get('cases',{}).get(key,{})
  cases.append(f'<article class="case-note"><p class="eyebrow">{c["article_id"]} · {"AI CDS" if key=="ai" else "韩国股市"}</p><h3>{E(c["title"])}</h3><p>{link("本地原文",p)} · {link("HTML阅读版",p.with_suffix(".html"))}</p>{rich(c_review.get("analysis","待汇总"))}<h4>结构判断</h4>{rich(c_review.get("structure","待汇总"))}<details><summary>核读一张相关图</summary><a href="{E(href(image))}"><img src="{E(href(image))}" alt="原文章图{fig}，点击查看原图"></a><p class="caption">本地图{fig:03d}；图内编号与本库序号分别保留。</p></details></article>')
 headline=review.get('headline','测试进行中')
 findings=review.get('findings',[])
 note=''.join(f'<li>{rich(s)}</li>'for s in findings)
 doclinks=link('通用制作纲领',LIB/'维护/ARTICLE_AUTHORING_CHARTER.md')+' · '+link('子层级讨论',ROOT/'说明/SUBSTRUCTURE_DISCUSSION.md')+' · '+link('试作任务',ROOT/'说明/TEST_TASK.md')
 doclinks+=' · '+' · '.join(link(n,ROOT/'说明'/n)for n in ['AUTHORING_STANDARD.md','NODE_SELECTION_GUIDE.md','EVENT_SOURCE_GUIDE.md','REVIEW_CHECKLIST.md'])
 return f'''<header><p class="eyebrow">FINANCIAL FOUNDATION / 2026.11.13</p><h1>从文章到认识，<br>再决定图的结构。</h1><p class="lead">两篇材料，各六次试作。检验通用制作思想能否迁移，以及子概念、子关系何时值得独立维护。</p><div class="stats"><div><strong>2</strong><span>篇原始材料</span></div><div><strong>{len(results)}</strong><span>份独立生成的试作</span></div><div><strong>0</strong><span>次正式节点注册</span></div></div></header><nav><a href="#findings">主要发现</a><a href="#cases">两篇材料</a><a href="#compare">结构选择</a><a href="#results">完整试作</a><a href="#inputs">纲领与说明</a></nav><main><section id="findings"><p class="eyebrow">判断与证据</p><h2>{E(headline)}</h2><ul class="findings">{note}</ul>{rich(review.get('next',''))}</section><section id="cases"><h2>同一纲领，处理两种问题</h2><div class="case-grid">{''.join(cases)}</div></section><section id="compare"><h2>12次结构选择</h2><p class="muted">下列均为试作建议。主agent逐份通读后整理意见；一致性不作为事实正确性或注册资格的证明。</p><div class="table-wrap"><table><thead><tr><th>试作</th><th>主要判断</th><th>建议维护的内容</th><th>主agent审阅意见</th></tr></thead><tbody>{''.join(table)}</tbody></table></div></section><section id="results"><h2>逐份查看分析与样稿</h2><div class="controls"><div role="group" aria-label="筛选文章"><button class="active" data-filter="all">全部</button><button data-filter="ai">AI CDS</button><button data-filter="korea">韩国股市</button></div><label>查找试作<input id="search" type="search" placeholder="标题、判断或结构名称"></label><p id="count" aria-live="polite">{len(results)}份</p></div>{''.join(cards)}</section><section id="inputs"><h2>纲领、测试说明与边界</h2><p>{doclinks}</p>{rich(review.get('instruction_findings',''))}<div class="boundary"><p>本轮测试的是材料理解、组织选择与内容样稿，正式graph保持只读。没有完成额外市场事实核验或正式稿接入。</p><p>12次运行均继承完整上下文。AI CDS已在此前会话中讨论；后续轮次也可能继承前轮简报。试作未互读成果文件，但不构成严格盲测或统计独立样本。模型和思考档位记为继承且未独立核验。</p><p>注册／不注册的建议都可成立，判断须回到具体内容与维护收益。图片阅读范围为agent自报，主agent另行核看两篇原文与相关图。</p></div><p>{link('运行与输入校验记录',ROOT/'run_manifest.json')} · {link('报告数据与审阅意见',ROOT/'review.json')}</p></section></main><footer>本地可读报告 · 原文、试作与审阅分开保存 · {len(results)} / 12 份结果</footer>'''
CSS='''
:root{--bg:#f5f2e9;--paper:#fffdf8;--ink:#20332e;--muted:#63736c;--line:#d8dfd4;--accent:#226b57}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.8 system-ui,"Microsoft YaHei",sans-serif}header,main,nav,footer{max-width:1240px;margin:auto}header{padding:64px 40px 32px}h1{font-size:clamp(36px,5.2vw,66px);line-height:1.25;letter-spacing:-.035em;margin:12px 0 22px;max-width:1000px}h2{font-size:30px;line-height:1.45;margin:8px 0 24px}h3{font-size:22px;line-height:1.55}h4{font-size:18px;margin:20px 0 10px}h5{font-size:16px;margin:15px 0 6px}a{color:var(--accent);text-underline-offset:3px;overflow-wrap:anywhere}p{margin:10px 0 16px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:.12em;color:var(--accent);text-transform:uppercase}.lead{font-size:20px;max-width:790px;color:var(--muted)}.stats{display:flex;gap:70px;margin-top:32px}.stats div{display:flex;flex-direction:column}.stats strong{font:500 36px/1.3 Georgia,serif}.stats span{font-size:13px;color:var(--muted);margin-top:6px}nav{display:flex;gap:24px;padding:14px 40px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);flex-wrap:wrap}nav a{font-size:14px;text-decoration:none}main{padding:0 40px}main>section{padding:46px 0;border-bottom:1px solid var(--line);scroll-margin-top:20px}.findings{padding-left:24px;font-size:18px}.findings li{padding:8px 0;max-width:1000px}.findings p{margin:0}.case-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.case-note{background:var(--paper);border:1px solid var(--line);padding:24px}.case-note h3{margin:6px 0 12px}.case-note img{max-width:100%;height:auto;margin-top:16px}.caption,.muted{color:var(--muted);font-size:14px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;background:var(--paper);font-size:14px}th,td{padding:16px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line)}th{color:var(--muted);font-size:12px;min-width:90px}td:nth-child(2){min-width:250px}td:nth-child(3){min-width:210px}td:nth-child(4){min-width:230px}.controls{display:flex;flex-wrap:wrap;align-items:end;gap:24px;margin:0 0 22px}.controls label{font-size:12px;color:var(--muted)}input{display:block;padding:10px 12px;background:var(--paper);border:1px solid #bfcbbb;font:inherit;min-width:290px}button{padding:10px 17px;border:1px solid #bfcbbb;color:var(--ink);background:transparent;font:inherit;cursor:pointer}.active{color:#fff;background:var(--accent);border-color:var(--accent)}details.agent{background:var(--paper);border:1px solid var(--line);margin:12px 0}summary{cursor:pointer}details.agent>summary{padding:20px;display:grid;grid-template-columns:85px 1fr 38px;gap:14px;align-items:start;list-style:none}.run{font-size:12px;font-weight:750;color:var(--accent);padding-top:4px}.expand{font-size:12px;color:var(--muted);padding-top:4px}details[open]>.inside{border-top:1px solid var(--line)}.inside{padding:12px 28px 28px}.inside h3{margin-top:30px}.passage{padding:12px 0;border-bottom:1px solid var(--line)}blockquote{border-left:3px solid #83a98e;margin:14px 0;padding:12px 18px;background:#eff3eb;white-space:pre-wrap}.method{font-size:14px;color:var(--muted)}.structure{padding:10px 0 18px;border-bottom:1px solid var(--line)}.pill{display:inline-block;font-size:11px;font-weight:500;border:1px solid #b6c9b5;padding:2px 9px;border-radius:20px;vertical-align:middle}.field{display:grid;grid-template-columns:120px 1fr;gap:12px;margin:7px 0}.field>b{font-size:12px;color:var(--muted);padding-top:4px}.field p{margin:0 0 8px}.sample{font-size:17px;padding:20px;background:#f6f4ec;border-left:3px solid #b19a67}.reading{font-size:13px;overflow-wrap:anywhere}.reading summary{margin-top:18px}.boundary{padding:18px 24px;background:#eaf0e5;font-size:14px;color:#485e50;margin-top:24px}footer{padding:28px 40px 50px;color:var(--muted);font-size:12px}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid #be9a40;outline-offset:3px}[hidden]{display:none!important}@media(max-width:800px){header{padding:32px 20px}main{padding:0 20px}nav{padding:14px 20px;gap:16px}.stats{gap:35px}.case-grid{grid-template-columns:1fr}h2{font-size:25px}.field{grid-template-columns:1fr;gap:0}details.agent>summary{grid-template-columns:72px 1fr}.expand{display:none}.inside{padding:8px 18px 20px}input{min-width:230px}main>section{padding:32px 0}}@media print{nav,.controls{display:none}.case-grid{display:block}details.agent{break-inside:avoid}body{background:white}}
'''
JS='''let selected='all';const q=document.getElementById('search');function filter(){const terms=q.value.trim().toLowerCase().split(/\\s+/);let n=0;document.querySelectorAll('.agent').forEach(x=>{const visible=(selected==='all'||x.dataset.case===selected)&&terms.every(t=>x.dataset.search.toLowerCase().includes(t));x.hidden=!visible;if(visible)n++});document.getElementById('count').textContent=n+'份'}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));filter()}));q.addEventListener('input',filter);document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{const target=document.querySelector(a.getAttribute('href'));if(target?.classList.contains('agent')){selected='all';q.value='';filter();target.open=true}}));'''
if __name__=='__main__':
 body=content();doc='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>文章制作思想与子层级试作报告</title><style>'+CSS+'</style></head><body>'+body+'<script>'+JS+'</script></body></html>';(ROOT/'报告.html').write_text(doc);print('report generated')
